<template>
  <view class="rpg-result" :style="viewportCss">
    <image class="rpg-result__bg" :src="assets.stadium" mode="aspectFill"/><view class="rpg-result__shade"/>
    <view class="rpg-result__card">
      <view class="rpg-result__header"><text>{{ completed?'训练完成':'训练未完成' }}</text><text>{{ completed?'本次康复训练已完成':'已保留当前训练数据' }}</text></view>
      <view class="rpg-result__columns">
        <view class="rpg-result__section"><text class="rpg-result__section-title">康复训练数据</text><view class="rpg-result__metrics">
          <view><text>左腿总次数</text><strong>{{ training.left_total_count }}</strong></view><view><text>右腿总次数</text><strong>{{ training.right_total_count }}</strong></view>
          <view><text>左腿最大ROM</text><strong>{{ fmt(training.session_left_rom_deg) }}°</strong></view><view><text>右腿最大ROM</text><strong>{{ fmt(training.session_right_rom_deg) }}°</strong></view>
          <view><text>完成组数</text><strong>{{ training.set_index }}/{{ training.target_sets }}</strong></view><view><text>整体完成度</text><strong>{{ training.overall_completion_percent }}%</strong></view>
        </view></view>
        <view class="rpg-result__section rpg-result__section--game"><text class="rpg-result__section-title">点球成绩</text><text class="rpg-result__score">{{ game.score }}<small> 分</small></text>
          <view class="rpg-result__row"><text>总射门</text><strong>{{ game.shots }}</strong></view><view class="rpg-result__row"><text>进球</text><strong>{{ game.goals }}</strong></view>
          <view class="rpg-result__row"><text>被扑 / 射偏</text><strong>{{ game.saves }} / {{ game.misses }}</strong></view><view class="rpg-result__row"><text>最大连击</text><strong>×{{ game.bestCombo }}</strong></view>
          <view class="rpg-result__row"><text>总用时 / 有效</text><strong>{{ seconds(elapsedMs) }} / {{ seconds(activeElapsedMs) }}秒</strong></view>
        </view>
      </view>
      <view class="rpg-result__actions"><button @click="again">再练一次</button><button class="rpg-result__back" @click="back">返回</button></view>
    </view>
  </view>
</template>
<script lang="ts">
import { PENALTY_ASSETS } from '../runtime/asset-paths';import { consumePenaltyResult,preparePenaltyReplay } from '../runtime/session-runtime'
import { appendReturnUrl,configureCallerReturnUrl,getCallerReturnUrl,returnToCaller } from '../../game-platform/runtime/navigation';import { getViewportLayout,viewportStyle } from '../../game-platform/runtime/viewport'
import type { PenaltyGameMetrics,PenaltyTrainingResult } from '../types/result'
const emptyTraining:PenaltyTrainingResult['training']={left_count:0,right_count:0,left_rom_deg:0,right_rom_deg:0,lr_rom_diff_deg:0,target_count:10,completion_percent:0,training_state:'STOPPED',set_index:1,target_sets:3,overall_completion_percent:0,left_total_count:0,right_total_count:0,session_left_rom_deg:0,session_right_rom_deg:0,session_lr_rom_diff_deg:0}
const emptyGame:PenaltyGameMetrics={shots:0,goals:0,saves:0,misses:0,score:0,combo:0,bestCombo:0}
export default{name:'RpgResult',data(){return{assets:PENALTY_ASSETS,result:null as PenaltyTrainingResult|null,training:{...emptyTraining},game:{...emptyGame},elapsedMs:0,activeElapsedMs:0,endReason:'STOPPED' as 'FINISHED'|'STOPPED',viewport:getViewportLayout()}},computed:{completed():boolean{return this.endReason==='FINISHED'},viewportCss():Record<string,string>{return viewportStyle(this.viewport,'--rpg-safe-top')}},onLoad(query:Record<string,string|undefined>){configureCallerReturnUrl(query?.returnUrl,'/pages-penalty-game/home/index');const r=consumePenaltyResult();if(r){this.result=r;this.training={...r.training};this.game={...r.game};this.elapsedMs=r.elapsedMs;this.activeElapsedMs=r.activeElapsedMs;this.endReason=r.endReason}},onResize(){this.viewport=getViewportLayout()},onBackPress(){this.back();return true},methods:{fmt(v:number){return Number(v).toFixed(1)},seconds(v:number){return Math.round(v/1000)},again(){preparePenaltyReplay();uni.redirectTo({url:appendReturnUrl('/pages-penalty-game/prepare/index?replay=1')})},back(){returnToCaller({delta:1,returnUrl:getCallerReturnUrl()})}}}
</script>
<style scoped>
