ult__actions .rpg-result__back{background:#2f9bdd;color:#fff}@media(max-height:390px){.rpg-result__card{padding:10px 20px}.rpg-result__columns{margin-top:8px}.rpg-result__metrics view{padding:4px}.rpg-result__metrics strong{font-size:18px}.rpg-result__score{font-size:32px}.rpg-result__actions{margin-top:8px}.rpg-result__actions button{height:40px}}
.rpg-result{height:100dvh}.rpg-result__card{max-height:calc(100dvh - var(--rpg-safe-top,8px) - 16px);overflow-x:hidden;overflow-y:auto}
@media(orientation:portrait),(max-width:520px){.rpg-result{align-items:flex-start;padding:calc(var(--rpg-safe-top,8px) + 6px) 10px 10px}.rpg-result__card{width:calc(100vw - 20px);padding:13px 15px}.rpg-result__header{align-items:flex-start;gap:8px}.rpg-result__header text:first-child{font-size:28px}.rpg-result__header text:last-child{max-width:48%;font-size:11px;text-align:right}.rpg-result__columns{display:flex;flex-direction:column;gap:8px;margin-top:8px}.rpg-result__section{padding:9px}.rpg-result__metrics{grid-template-columns:repeat(2,minmax(0,1fr));gap:6px}.rpg-result__metrics view{min-width:0}.rpg-result__actions{gap:9px}.rpg-result__actions button{flex:1;width:auto;height:42px;font-size:16px;white-space:nowrap}}
</style>
